steps.code:
// 위치·정밀 위치 권한은 begin() 이 엔진을 켤 때 SDK 가 직접 요청한다 — 앱은 Info.plist 문구만 넣는다.
// Nearby Interaction 권한은 확인과 요청이 분리되지 않는다 — 부르는 순간 시스템 창이 뜬다.
switch await OneS1ght.requestPermission() {
case .authorized:  break
case .denied:      showSettingsGuide()      // 앱에서 재요청 불가 — 설정 앱으로
case .unsupported: showUnsupportedNotice()
@unknown default:  break
}

import OneS1ght

try await OneS1ght.initialize(
    sdkKey: "ock_sdk_..."         // OneS1ght 콘솔 발급 — 측위·지도 키는 콘솔에서 내려온다
)

// 최초 1회 — 발급받아 앱에 저장(UserDefaults·Keychain 등)
// ⚠️ `savedProfileId ?? (try await ...)` 는 컴파일되지 않는다 —
//    `??` 오른쪽은 autoclosure 라 try/await 를 담을 수 없다.
let profileId: String
if let saved = savedProfileId {
    profileId = saved
} else {
    profileId = try await OneS1ght.createProfile([
        "gender":  "F",
        "ageBand": "20s"          // 정확한 나이가 아니라 연령대
    ])
}

// 매 실행 — 저장해 둔 값을 연결
OneS1ght.identify(profileId: profileId)

let buildings = try await OneS1ght.buildings()
let floors    = try await OneS1ght.floors(buildingId: buildings[0].id)

try await OneS1ght.setFloorMap(floors[0], buildingId: buildings[0].id)

// 엔진이 BLE 로 찾은 층을 따라가려면 — floorId 는 Floor.id 와 같은 값이다
let session = try OneS1ght.floorSession()
session.onFloorDetected = { floorId in
    guard let floorId else { return }        // nil = 층을 잃음
    showFloor(floorId)
}

// floors(buildingId:) 는 목록을 가볍게 유지하려고 image 가 비어 있다.
// 그릴 층 하나만 다시 조회한다 — 도면은 캐시되고 콘솔이 도면을 바꾸면(.planChanged) 버려진다.
let floor = try await OneS1ght.floor(buildingId: buildingID, floorId: floorID)

mapView.setBackground(floor.image,
                      bounds: (floor.minX, floor.minY, floor.maxX, floor.maxY))

let session = try OneS1ght.floorSession()

session.onPosition  = { coord in mapView.moveMarker(coord) }
session.onZoneEnter = { zone in showCoupon(zone) }
session.onZoneExit  = { zone in hideCoupon(zone) }
session.onZoneDwell = { zone, seconds in logDwell(zone, seconds) }   // dwellSeconds 가 있는 존만, 방문당 1회
session.onTriggers  = { zoneId, triggers in handle(triggers) }
session.onStopped   = { reason in
    switch reason {
    case .ended:        break
    case .engineFailed: showRetry()          // 권한·Bluetooth 를 풀고 begin() 을 다시 부른다
    @unknown default:   break
    }
}

try await session.begin()

let session = try OneS1ght.floorSession()

session.pause()      // 좌표 표시·전송·구역 판정만 멈춘다 (엔진은 계속 돈다)
session.resume()     // 즉시 이어진다 — 로케이터를 다시 찾지 않는다

if session.isPaused { showPausedBadge() }

let session = try OneS1ght.floorSession()

session.onConfigChanged = { change in
    // 층을 정했거나 측위가 도는 동안 붙어 있는 실시간 연결로 온다
    switch change {
    case .zonesChanged, .resyncNeeded: Task { await OneS1ght.refreshZones() }
    case .planChanged:                 reloadOverlay()
    case .rulesChanged, .sdkConfigChanged: break
    @unknown default:                  break
    }
}

// 네트워크를 타지 않고 즉시 답한다 — initialize 전에도 부를 수 있다.
switch OneS1ght.deviceAvailability {
case .available:          break
case .osVersionTooLow:    showNotice("iOS 27 이상이 필요합니다")
case .deviceNotSupported: hidePositioningFeatures()
}

#if DEBUG
OneS1ght.onDebugLog = { level, line in print("[OneS1ght][\(level)] \(line)") }
#endif
